295	            try {
296	                const details = db.getMeetingDetails(m.id);
297	                if (!details) continue;
298	
299	                console.log(`[MeetingPersistence] Recovering meeting ${m.id}...`);
300	
301	                const context = details.transcript?.map(t => {
302	                    const label = t.speaker === 'interviewer' ? 'INTERVIEWER' :
303	                        t.speaker === 'user' ? 'ME' : 'ASSISTANT';
304	                    return `[${label}]: ${t.text}`;
305	                }).join('\n') || "";
306	
307	                const parts = (details.duration || '0:00').split(':');
308	                // EC-07 fix: guard against malformed duration strings (e.g. corrupted DB row)
309	                const mins = parseInt(parts[0]) || 0;
310	                const secs = parseInt(parts[1]) || 0;
311	                const durationMs = ((mins * 60) + secs) * 1000;
