112	
113	        // 1. Preprocess transcript
114	        const cleaned = preprocessTranscript(transcript);
115	        console.log(`[RAGManager] Preprocessed to ${cleaned.length} cleaned segments`);
116	
117	        // 2. Chunk the transcript
118	        const chunks = chunkTranscript(meetingId, cleaned);
119	        console.log(`[RAGManager] Created ${chunks.length} chunks`);
120	
121	        if (chunks.length === 0) {
122	            console.log(`[RAGManager] No chunks to save for meeting ${meetingId}`);
123	            return { chunkCount: 0 };
124	        }
125	
126	        // 3. Save chunks to database
127	        this.vectorStore.saveChunks(chunks);
128	
129	        // 4. Save summary if provided
130	        if (summary) {
131	            this.vectorStore.saveSummary(meetingId, summary);
132	        }
133	
134	        // 5. Queue for embedding (background processing)
